import { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell, WidthType, BorderStyle, AlignmentType, VerticalAlign, TabStopType, TabStopPosition } from 'docx';
import saveAs from 'file-saver';
import type { LessonPlan, LessonPlan1001, Activity1001, LessonPlan5512, Activity5512 } from '../types';

const FONT_FAMILY = "Times New Roman";
const FONT_SIZE = 26; // 13pt * 2
const INDENT_FIRST_LINE = 720; // 0.5 inch indent

// Fix: Corrected the type definition by removing an extra 'typeof'.
type TAlignmentType = (typeof AlignmentType)[keyof typeof AlignmentType];

const createParagraph = (text: string, options: { bold?: boolean; isTitle?: boolean; alignment?: TAlignmentType; indent?: { firstLine?: number } } = {}) => {
  return new Paragraph({
    children: [
      new TextRun({
        text,
        font: FONT_FAMILY,
        size: options.isTitle ? 32 : FONT_SIZE,
        bold: options.bold || options.isTitle,
      }),
    ],
    spacing: { after: 120 },
    alignment: options.alignment ?? AlignmentType.JUSTIFIED,
    indent: options.indent,
  });
};

const createRichParagraph = (
    parts: { text: string; bold?: boolean; italics?: boolean }[], 
    options: { alignment?: TAlignmentType; indent?: { firstLine?: number } } = {}
) => {
  const { alignment = AlignmentType.JUSTIFIED, indent } = options;
  return new Paragraph({
    children: parts.map(part => new TextRun({
        text: part.text,
        font: FONT_FAMILY,
        size: FONT_SIZE,
        bold: part.bold,
        italics: part.italics,
    })),
    spacing: { after: 120 },
    alignment: alignment,
    indent: indent,
  });
}

// --- CV 1001 DOCX Generation ---
const createActivitiesTable1001 = (activities: Activity1001[], t: (key: string) => string) => {
    const cellMargins = { left: 100, right: 100, top: 80, bottom: 80 };
    const rows = [
        new TableRow({
            children: [
                new TableCell({
                    children: [createParagraph(t('docxTeacherActivity'), { bold: true, alignment: AlignmentType.LEFT })],
                    width: { size: 50, type: WidthType.PERCENTAGE },
                    margins: cellMargins,
                }),
                new TableCell({
                    children: [createParagraph(t('docxStudentActivity'), { bold: true, alignment: AlignmentType.LEFT })],
                    width: { size: 50, type: WidthType.PERCENTAGE },
                    margins: cellMargins,
                }),
            ],
            tableHeader: true,
        }),
    ];

    activities.forEach(activity => {
        rows.push(
            new TableRow({
                children: [
                    new TableCell({
                        children: [
                            createParagraph(activity.activityName, { bold: true, alignment: AlignmentType.LEFT }),
                            createRichParagraph([{ text: `${t('objective')} `, bold: true, italics: true }, { text: activity.objective, italics: true }]),
                        ],
                        columnSpan: 2,
                        margins: cellMargins,
                    }),
                ],
            })
        );

        const teacherActivityParas = activity.teacherActivity.split('\n').map(line => new Paragraph({
            children: [new TextRun({ text: line, font: FONT_FAMILY, size: FONT_SIZE })],
            spacing: { after: 100 },
            alignment: AlignmentType.JUSTIFIED,
        }));

        const studentActivityParas = activity.studentActivity.split('\n').map(line => new Paragraph({
            children: [new TextRun({ text: line, font: FONT_FAMILY, size: FONT_SIZE })],
            spacing: { after: 100 },
            alignment: AlignmentType.JUSTIFIED,
        }));

        rows.push(
            new TableRow({
                children: [
                    new TableCell({
                        children: [createParagraph(t('teachingMethod'), { bold: true, alignment: AlignmentType.LEFT }), ...teacherActivityParas],
                        verticalAlign: VerticalAlign.TOP,
                        margins: cellMargins,
                    }),
                     new TableCell({
                        children: [...studentActivityParas],
                        verticalAlign: VerticalAlign.TOP,
                        margins: cellMargins,
                    }),
                ],
            })
        );
    });

    return new Table({
        rows,
        width: { size: 100, type: WidthType.PERCENTAGE },
        borders: {
            top: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
            bottom: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
            left: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
            right: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
            insideHorizontal: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
            insideVertical: { style: BorderStyle.SINGLE, size: 1, color: "000000" },
        },
    });
};

const generateDocx1001 = (plans: LessonPlan1001[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];

    plans.forEach((plan, index) => {
        if (index > 0) {
            children.push(new Paragraph({ pageBreakBefore: true }));
        }

        children.push(
          new Paragraph({
            text: `${t('lessonPlanTitle')} (${t('period')} ${index + 1})`,
            heading: HeadingLevel.HEADING_1,
            alignment: AlignmentType.CENTER,
            style: "Title",
          }),
          createRichParagraph([
              {text: `${t('subject')}: `, bold: true}, {text: `${plan.subject}; `},
              {text: `${t('grade')}: `, bold: true}, {text: plan.grade},
          ], { alignment: AlignmentType.CENTER }),
          createRichParagraph([
              {text: `${t('lessonTitleLabel')}: `, bold: true}, {text: `${plan.lessonTitle}; `},
              {text: `${t('periods')}: `, bold: true}, {text: String(plan.periods)},
          ], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{text: `${t('executionTime')}: `, bold: true}, {text: plan.executionTime}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{ text: t('docxDate'), italics: true }], { alignment: AlignmentType.CENTER }),

          new Paragraph({ text: t('requiredOutcomes'), heading: HeadingLevel.HEADING_2, style: "Heading2" }),
          createRichParagraph([{text: `${t('generalCompetencies')} `, bold: true}, {text: plan.requiredOutcomes.generalCompetencies}], { indent: { firstLine: INDENT_FIRST_LINE } }),
          createRichParagraph([{text: `${t('specificCompetencies')} `, bold: true}, {text: plan.requiredOutcomes.specificCompetencies}], { indent: { firstLine: INDENT_FIRST_LINE } }),
          createRichParagraph([{text: `${t('qualities')} `, bold: true}, {text: plan.requiredOutcomes.qualities}], { indent: { firstLine: INDENT_FIRST_LINE } }),
          createRichParagraph([{text: `${t('integratedContent')} `, bold: true}, {text: plan.requiredOutcomes.integratedContent}], { indent: { firstLine: INDENT_FIRST_LINE } })
        );

        children.push(
          new Paragraph({ text: t('teachingAids'), heading: HeadingLevel.HEADING_2, style: "Heading2" }),
          createRichParagraph([{text: `${t('teacherAids')} `, bold: true}, {text: plan.teachingAids.teacher}], { indent: { firstLine: INDENT_FIRST_LINE } }),
          createRichParagraph([{text: `${t('studentAids')} `, bold: true}, {text: plan.teachingAids.student}], { indent: { firstLine: INDENT_FIRST_LINE } }),
          new Paragraph({ text: t('teachingActivities'), heading: HeadingLevel.HEADING_2, style: "Heading2" }),
          createActivitiesTable1001(plan.teachingActivities, t),
          new Paragraph({ text: t('postLessonAdjustments'), heading: HeadingLevel.HEADING_2, style: "Heading2" }),
          ...[...Array(3)].map(() => new Paragraph({
              children: [new TextRun("\t")],
              tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX, leader: 'dot' }],
              spacing: { after: 360 },
          }))
        );
    });
    return children;
};

// --- CV 5512 DOCX Generation ---
const createActivityBox5512 = (activity: Activity5512, t: (key: string) => string): Table => {
    // Helper to create a single paragraph for a section, preserving line breaks from the AI.
    const createSectionParagraph = (labelKey: string, content: string): Paragraph => {
        const textRuns: TextRun[] = [
            new TextRun({ text: t(labelKey) + " ", bold: true, font: FONT_FAMILY, size: FONT_SIZE }),
        ];

        // Split content by newlines and add them with breaks
        const lines = content.split('\n');
        lines.forEach((line, index) => {
            textRuns.push(new TextRun({ text: line, font: FONT_FAMILY, size: FONT_SIZE }));
            if (index < lines.length - 1) {
                textRuns.push(new TextRun({ break: 1 }));
            }
        });

        return new Paragraph({
            children: textRuns,
            spacing: { after: 120 },
            alignment: AlignmentType.JUSTIFIED,
        });
    };

    const contentParagraphs = [
        createSectionParagraph('objective', activity.objective),
        createSectionParagraph('content', activity.content),
        createSectionParagraph('product', activity.product),
        createSectionParagraph('implementation', activity.implementation),
    ];

    const cellMargins = { top: 100, bottom: 100, left: 100, right: 100 };

    return new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: [
            // Row 1: Activity Title
            new TableRow({
                children: [
                    new TableCell({
                        children: [new Paragraph({ text: activity.activityName, style: "Heading3" })],
                        shading: { fill: "EAEAEA" }, // Light gray background
                        margins: cellMargins,
                    }),
                ],
            }),
            // Row 2: Content
            new TableRow({
                children: [
                    new TableCell({
                        children: contentParagraphs,
                        margins: cellMargins,
                    }),
                ],
            }),
        ],
        borders: {
            top: { style: BorderStyle.SINGLE, size: 6, color: "000000" },
            bottom: { style: BorderStyle.SINGLE, size: 6, color: "000000" },
            left: { style: BorderStyle.SINGLE, size: 6, color: "000000" },
            right: { style: BorderStyle.SINGLE, size: 6, color: "000000" },
            insideHorizontal: { style: BorderStyle.SINGLE, size: 6, color: "000000" },
        },
    });
};

const generateDocx5512 = (plans: LessonPlan5512[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];

    plans.forEach((plan, index) => {
        if (index > 0) {
            children.push(new Paragraph({ pageBreakBefore: true }));
        }

        const headerTable = new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
                top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
                bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
                left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
                right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
                insideHorizontal: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
                insideVertical: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
            },
            rows: [
                new TableRow({
                    children: [
                        new TableCell({
                            children: [
                                createRichParagraph([{text: `${t('docxSchool')}: `, bold: true}, {text: plan.school}], { alignment: AlignmentType.LEFT }),
                                createRichParagraph([{text: `${t('docxDepartment')}: `, bold: true}, {text: plan.department}], { alignment: AlignmentType.LEFT }),
                            ],
                            width: { size: 60, type: WidthType.PERCENTAGE },
                            verticalAlign: VerticalAlign.TOP,
                        }),
                        new TableCell({
                            children: [
                                createRichParagraph([{text: `${t('docxTeacher')}: `, bold: true}, {text: plan.teacherName}], { alignment: AlignmentType.LEFT }),
                            ],
                            width: { size: 40, type: WidthType.PERCENTAGE },
                            verticalAlign: VerticalAlign.TOP,
                        }),
                    ],
                }),
            ],
        });


        children.push(
            new Paragraph({ text: t('lessonPlanTitle'), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, style: "Title" }),
            createRichParagraph([{text: `(${t('period')} ${index + 1})`}], { alignment: AlignmentType.CENTER }),
            headerTable,

            new Paragraph({ text: '' }),
            createRichParagraph([{text: `${t('lessonTitleLabel')}: `, bold: true}, {text: plan.lessonTitle}], { alignment: AlignmentType.CENTER }),
            createRichParagraph([{text: `${t('subject')}: `, bold: true}, {text: `${plan.subject}; `}, {text: `${t('grade')}: `, bold: true}, {text: plan.grade}], { alignment: AlignmentType.CENTER }),
            createRichParagraph([{text: `${t('executionTime')}: `, bold: true}, {text: `${plan.periods} ${t('period').toLowerCase()}`}], { alignment: AlignmentType.CENTER }),

            new Paragraph({ text: t('objectives'), heading: HeadingLevel.HEADING_2, style: "Heading2" }),
            createRichParagraph([{text: `${t('knowledge')}: `, bold: true}, {text: plan.objectives.knowledge}], { indent: { firstLine: INDENT_FIRST_LINE } }),
            createRichParagraph([{text: `${t('skills')}: `, bold: true}, {text: plan.objectives.skills}], { indent: { firstLine: INDENT_FIRST_LINE } }),
            createRichParagraph([{text: `${t('qualities')}: `, bold: true}, {text: plan.objectives.qualities}], { indent: { firstLine: INDENT_FIRST_LINE } })
        );

        children.push(
            new Paragraph({ text: t('teachingAidsAndMaterials'), heading: HeadingLevel.HEADING_2, style: "Heading2" }),
            ...plan.teachingAidsAndMaterials.split('\n').filter(line => line.trim() !== '').map(line => createParagraph(line, { indent: { firstLine: INDENT_FIRST_LINE } })),

            new Paragraph({ text: t('teachingProcess'), heading: HeadingLevel.HEADING_2, style: "Heading2" }),
            ...plan.teachingProcess.flatMap(activity => [
                createActivityBox5512(activity, t),
                new Paragraph({ text: '' }), // Spacer
            ])
        );
    });
    return children;
};


export const exportToDocx = async (plans: LessonPlan[], t: (key: string) => string, periodLabel?: string) => {
    if (!plans || plans.length === 0) return;

    const template = plans[0].template;
    const children = template === 'cv5512' 
      ? generateDocx5512(plans as LessonPlan5512[], t) 
      : generateDocx1001(plans as LessonPlan1001[], t);

    const doc = new Document({
      sections: [{ children }],
      styles: {
          paragraphStyles: [
              { id: "Title", name: "Title", basedOn: "Normal", next: "Normal", run: { font: FONT_FAMILY, size: 32, bold: true } },
              { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", run: { font: FONT_FAMILY, size: FONT_SIZE, bold: true } },
              { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", run: { font: FONT_FAMILY, size: FONT_SIZE, bold: true } },
          ]
      }
    });

    const firstPlan = plans[0];
    const periodSuffix = periodLabel ? `_Tiet_${periodLabel}` : "";
    const fileName = `${t('docxFilenamePrefix')}_${firstPlan.subject.replace(/\s/g, '_')}_${firstPlan.lessonTitle.replace(/\s/g, '_')}${periodSuffix}.docx`
    const blob = await Packer.toBlob(doc);
    saveAs(blob, fileName);
};

import React, { useState, useCallback, useEffect } from 'react';
import { LessonPlanForm } from './components/LessonPlanForm';
import { LessonPlanDisplay } from './components/LessonPlanDisplay';
import { LanguageSwitcher } from './components/LanguageSwitcher';
import { useI18n } from './contexts/I18nContext';
import { LessonPlan, LessonPlanInput, FileWithPreview } from './types';
import { generateLessonPlan } from './services/geminiService';
import { exportToDocx } from './utils/docxGenerator';
import { RobotIcon, KeyIcon } from './components/icons';
import { Auth } from './components/Auth';

export default function App() {
  const [apiKey, setApiKey] = useState<string | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const [lessonPlan, setLessonPlan] = useState<LessonPlan[] | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { t, locale } = useI18n();

  useEffect(() => {
    const storedKey = localStorage.getItem('gemini-api-key');
    if (storedKey) {
      setApiKey(storedKey);
    }
  }, []);

  const handleKeySubmit = (key: string) => {
    localStorage.setItem('gemini-api-key', key);
    setApiKey(key);
    setAuthError(null); // Clear previous auth errors on new submission
  };

  const handleKeyChange = () => {
    localStorage.removeItem('gemini-api-key');
    setApiKey(null);
  };

  const handleGeneratePlan = useCallback(async (data: LessonPlanInput, files: FileWithPreview[]) => {
    if (!apiKey) {
      setError(t('apiKeyMissingError')); // Should not happen if UI is correct
      return;
    }
    setIsLoading(true);
    setError(null);
    setLessonPlan(null);
    setAuthError(null);

    try {
      const result = await generateLessonPlan(data, files, locale, apiKey);
      setLessonPlan(result);
    } catch (err) {
      console.error(err);
      if (err instanceof Error) {
        if (err.message.includes('API_KEY_INVALID')) {
          setAuthError(t('invalidApiKeyError'));
          handleKeyChange();
        } else {
          setError(err.message);
        }
      } else {
        setError(t('unexpectedError'));
      }
    } finally {
      setIsLoading(false);
    }
  }, [apiKey, locale, t]);

  const handleReset = useCallback(() => {
    setLessonPlan(null);
    setError(null);
  }, []);

  const handleDownload = useCallback(async (plans: LessonPlan[], label?: string) => {
    if (plans && plans.length > 0) {
      await exportToDocx(plans, t, label);
    }
  }, [t]);

  if (!apiKey) {
    return <Auth onSubmit={handleKeySubmit} error={authError} />;
  }

  return (
    <div className="h-screen bg-gray-100 flex flex-col">
      <header className="bg-white shadow-sm z-10 flex-shrink-0">
        <div className="max-w-7xl mx-auto py-4 px-4 sm:px-6 lg:px-8 grid grid-cols-3 items-center">
           <div /> {/* Left empty cell for spacing */}
           <div className="text-center col-span-1">
            <h1 className="text-3xl font-bold text-blue-600 leading-tight flex items-center justify-center">
              <RobotIcon className="w-8 h-8 mr-3" />
              <span>{t('headerTitle')}</span>
            </h1>
            <p className="text-base text-gray-900 mt-1 font-bold whitespace-pre-line">{t('headerSubtitle')}</p>
          </div>
          <div className="flex items-center space-x-4 justify-self-end">
             <button
                onClick={handleKeyChange}
                className="flex items-center px-3 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                title={t('changeApiKeyButton')}
              >
                <KeyIcon className="w-4 h-4 mr-2" />
                {t('changeApiKeyButton')}
            </button>
            <LanguageSwitcher />
          </div>
        </div>
      </header>
      <main className="max-w-7xl w-full mx-auto py-6 sm:px-6 lg:px-8 flex-grow overflow-hidden">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
          <div className="lg:col-span-5 overflow-y-auto custom-scrollbar pr-4">
            <LessonPlanForm onSubmit={handleGeneratePlan} isLoading={isLoading} onReset={handleReset} />
          </div>
          <div className="lg:col-span-7 bg-white p-6 rounded-lg shadow-md overflow-y-auto custom-scrollbar">
            <LessonPlanDisplay
              lessonPlan={lessonPlan}
              isLoading={isLoading}
              error={error}
              onDownload={handleDownload}
            />
          </div>
        </div>
      </main>
       <footer className="text-center py-4 text-sm text-gray-500 flex-shrink-0">
        <p>{t('footerText')}</p>
      </footer>
    </div>
  );
}

