        }

        children.push(
          new Paragraph({
            text: `${t('lessonPlanTitle')} (${t('period')} ${index + 1})`,
            heading: HeadingLevel.HEADING_1,
            alignment: AlignmentType.CENTER,
            style: "Title",
          }),
          createRichParagraph([{text: plan.lessonTitle, bold: true, size: 28}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([
              {text: `${t('subject')}: `, bold: true}, {text: `${plan.subject}; `},
              {text: `${t('grade')}: `, bold: true}, {text: `${plan.grade}; `},
