const SPACING_CONFIG = { before: 0, after: 0, line: 240, lineRule: 'auto' as const };

type TAlignmentType = (typeof AlignmentType)[keyof typeof AlignmentType];

const createParagraph = (text: string, options: { bold?: boolean; isTitle?: boolean; alignment?: TAlignmentType; indent?: { firstLine?: number } } = {}) => {
  return new Paragraph({
