import { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell, WidthType, BorderStyle, AlignmentType, VerticalAlign, TabStopType, TabStopPosition, PageOrientation } from 'docx';
import saveAs from 'file-saver';
import type { LessonPlan, LessonPlan1001, Activity1001, LessonPlan5512, Activity5512 } from '../types';

const FONT_FAMILY = "Times New Roman";
const FONT_SIZE = 26; // 13pt * 2
const INDENT_FIRST_LINE = 720; // 0.5 inch indent

const MARGIN_TOP = 1134;    // 2.0 cm
const MARGIN_BOTTOM = 1134; // 2.0 cm
const MARGIN_LEFT = 1701;   // 3.0 cm
const MARGIN_RIGHT = 850;   // 1.5 cm

const SPACING_CONFIG = { before: 0, after: 0, line: 240, lineRule: 'auto' as const };

type TAlignmentType = (typeof AlignmentType)[keyof typeof AlignmentType];

// Hàm hỗ trợ tạo nhiều đoạn văn từ một chuỗi có dấu xuống dòng
const createMultiParagraphs = (text: string, options: { boldLabel?: string; bold?: boolean; indent?: { firstLine?: number }; alignment?: TAlignmentType } = {}) => {
  const lines = text.split('\n').filter(l => l.trim() !== '');
  return lines.map((line, idx) => {
    const children = [];
    if (idx === 0 && options.boldLabel) {
      children.push(new TextRun({ text: options.boldLabel, font: FONT_FAMILY, size: FONT_SIZE, bold: true }));
    }
    children.push(new TextRun({ text: line, font: FONT_FAMILY, size: FONT_SIZE, bold: options.bold }));

    return new Paragraph({
      children,
      spacing: SPACING_CONFIG,
      alignment: options.alignment ?? AlignmentType.JUSTIFIED,
      indent: idx === 0 ? undefined : options.indent, // Chỉ indent các dòng sau nếu cần, hoặc tùy chỉnh theo yêu cầu
    });
  });
};

const createRichParagraph = (
    parts: { text: string; bold?: boolean; italics?: boolean; size?: number }[], 
    options: { alignment?: TAlignmentType; indent?: { firstLine?: number } } = {}
) => {
  return new Paragraph({
    children: parts.map(part => new TextRun({
        text: part.text,
        font: FONT_FAMILY,
        size: part.size ?? FONT_SIZE,
        bold: part.bold,
        italics: part.italics,
    })),
    spacing: SPACING_CONFIG,
    alignment: options.alignment ?? AlignmentType.JUSTIFIED,
    indent: options.indent,
  });
}

const createActivitiesTable1001 = (activities: Activity1001[], t: (key: string) => string) => {
    const cellMargins = { left: 100, right: 100, top: 80, bottom: 80 };
    const rows = [
        new TableRow({
            children: [
                new TableCell({
                    children: [new Paragraph({ children: [new TextRun({ text: t('docxTeacherActivity'), bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG })],
                    width: { size: 50, type: WidthType.PERCENTAGE },
                    margins: cellMargins,
                }),
                new TableCell({
                    children: [new Paragraph({ children: [new TextRun({ text: t('docxStudentActivity'), bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG })],
                    width: { size: 50, type: WidthType.PERCENTAGE },
                    margins: cellMargins,
                }),
            ],
            tableHeader: true,
        }),
    ];

    activities.forEach(activity => {
        rows.push(
            new TableRow({
                children: [
                    new TableCell({
                        children: [
                            new Paragraph({ children: [new TextRun({ text: activity.activityName, bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG }),
                            createRichParagraph([{ text: `${t('objective')} `, bold: true, italics: true }, { text: activity.objective, italics: true }]),
                        ],
                        columnSpan: 2,
                        margins: cellMargins,
                    }),
                ],
            })
        );

        rows.push(
            new TableRow({
                children: [
                    new TableCell({
                        children: [
                          new Paragraph({ children: [new TextRun({ text: t('teachingMethod'), bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG }),
                          ...activity.teacherActivity.split('\n').map(l => new Paragraph({ children: [new TextRun({ text: l, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG, alignment: AlignmentType.JUSTIFIED }))
                        ],
                        verticalAlign: VerticalAlign.TOP,
                        margins: cellMargins,
                    }),
                     new TableCell({
                        children: activity.studentActivity.split('\n').map(l => new Paragraph({ children: [new TextRun({ text: l, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG, alignment: AlignmentType.JUSTIFIED })),
                        verticalAlign: VerticalAlign.TOP,
                        margins: cellMargins,
                    }),
                ],
            })
        );
    });

    return new Table({ rows, width: { size: 100, type: WidthType.PERCENTAGE }, borders: { top: { style: BorderStyle.SINGLE, size: 1 }, bottom: { style: BorderStyle.SINGLE, size: 1 }, left: { style: BorderStyle.SINGLE, size: 1 }, right: { style: BorderStyle.SINGLE, size: 1 }, insideHorizontal: { style: BorderStyle.SINGLE, size: 1 }, insideVertical: { style: BorderStyle.SINGLE, size: 1 } } });
};

const generateDocx1001 = (plans: LessonPlan1001[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];
    plans.forEach((plan, index) => {
        if (index > 0) children.push(new Paragraph({ pageBreakBefore: true }));

        children.push(
          new Paragraph({ text: t('lessonPlanTitle'), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, style: "Title", spacing: { ...SPACING_CONFIG, after: 120 } }),
          createRichParagraph([{text: plan.lessonTitle, bold: true, size: 28}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{text: `${t('subject')}: `, bold: true}, {text: `${plan.subject}; `}, {text: `${t('grade')}: `, bold: true}, {text: `${plan.grade}; `}, {text: `${t('periods')}: `, bold: true}, {text: String(plan.periods)}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{text: `${t('executionTime')}: `, bold: true}, {text: `${plan.executionTime} `}, {text: `(${t('docxDate')})`, italics: true}], { alignment: AlignmentType.CENTER }),

          new Paragraph({ text: t('requiredOutcomes'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
          ...createMultiParagraphs(plan.requiredOutcomes.generalCompetencies, { boldLabel: t('generalCompetencies') + " " }),
          createRichParagraph([{text: `${t('specificCompetencies')} `, bold: true}, {text: plan.requiredOutcomes.specificCompetencies}]),
          createRichParagraph([{text: `${t('qualities')} `, bold: true}, {text: plan.requiredOutcomes.qualities}]),
          ...createMultiParagraphs(plan.requiredOutcomes.integratedContent, { boldLabel: t('integratedContent') + " " }),

          new Paragraph({ text: t('teachingAids'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
          createRichParagraph([{text: `${t('teacherAids')} `, bold: true}, {text: plan.teachingAids.teacher}]),
          createRichParagraph([{text: `${t('studentAids')} `, bold: true}, {text: plan.teachingAids.student}]),

          new Paragraph({ text: t('teachingActivities'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
          createActivitiesTable1001(plan.teachingActivities, t)
        );
    });
    return children;
};

const generateDocx5512 = (plans: LessonPlan5512[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];
    plans.forEach((plan, index) => {
        if (index > 0) children.push(new Paragraph({ pageBreakBefore: true }));

        children.push(
            new Paragraph({ text: t('lessonPlanTitle'), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, style: "Title", spacing: { ...SPACING_CONFIG, after: 120 } }),
            createRichParagraph([{text: plan.lessonTitle, bold: true, size: 28}], { alignment: AlignmentType.CENTER }),

            new Paragraph({ text: t('objectives'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
            createRichParagraph([{text: `${t('knowledge')}: `, bold: true}, {text: plan.objectives.knowledge}]),
            ...createMultiParagraphs(plan.objectives.skills, { boldLabel: `${t('skills')}: ` }),
            createRichParagraph([{text: `${t('qualities')}: `, bold: true}, {text: plan.objectives.qualities}]),

            new Paragraph({ text: t('teachingProcess'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
            ...plan.teachingProcess.flatMap(activity => [
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({ children: [new TableCell({ children: [new Paragraph({ text: activity.activityName, style: "Heading3", spacing: SPACING_CONFIG })], shading: { fill: "F2F2F2" } })] }),
                        new TableRow({ children: [new TableCell({ children: [
                            ...createMultiParagraphs(activity.objective, { boldLabel: t('objective') + " " }),
                            ...createMultiParagraphs(activity.content, { boldLabel: t('content') + " " }),
                            ...createMultiParagraphs(activity.product, { boldLabel: t('product') + " " }),
                            ...createMultiParagraphs(activity.implementation, { boldLabel: t('implementation') + " " })
                        ]})] })
                    ]
                }),
                new Paragraph({ text: "" })
            ])
        );
    });
    return children;
};

export const exportToDocx = async (plans: LessonPlan[], t: (key: string) => string, periodLabel?: string) => {
    if (!plans || plans.length === 0) return;
    const template = plans[0].template;
    const children = template === 'cv5512' ? generateDocx5512(plans as LessonPlan5512[], t) : generateDocx1001(plans as LessonPlan1001[], t);

    const doc = new Document({
      sections: [{ 
          properties: { page: { size: { width: 11906, height: 16838, orientation: PageOrientation.PORTRAIT }, margin: { top: MARGIN_TOP, bottom: MARGIN_BOTTOM, left: MARGIN_LEFT, right: MARGIN_RIGHT } } },
          children 
      }],
      styles: {
          paragraphStyles: [
              { id: "Title", name: "Title", basedOn: "Normal", run: { font: FONT_FAMILY, size: 32, bold: true } },
              { id: "Heading2", name: "Heading 2", basedOn: "Normal", run: { font: FONT_FAMILY, size: 28, bold: true } },
              { id: "Heading3", name: "Heading 3", basedOn: "Normal", run: { font: FONT_FAMILY, size: 26, bold: true } },
          ]
      }
    });

    const blob = await Packer.toBlob(doc);
    saveAs(blob, `GiaoAn_${plans[0].subject}_${plans[0].lessonTitle}.docx`);
};

import { GoogleGenAI, Type } from "@google/genai";
