const FONT_FAMILY = "Times New Roman";
const FONT_SIZE = 26; // 13pt * 2
const INDENT_FIRST_LINE = 720; // 0.5 inch indent

const MARGIN_TOP = 1134;    // 2.0 cm
const MARGIN_BOTTOM = 1134; // 2.0 cm
const MARGIN_LEFT = 1701;   // 3.0 cm
const MARGIN_RIGHT = 850;   // 1.5 cm

const SPACING_CONFIG = { before: 0, after: 0, line: 240, lineRule: 'auto' as const };

type TAlignmentType = (typeof AlignmentType)[keyof typeof AlignmentType];

// Hàm hỗ trợ tạo nhiều đoạn văn từ một chuỗi có dấu xuống dòng
const createMultiParagraphs = (text: string, options: { boldLabel?: string; bold?: boolean; indent?: { firstLine?: number }; alignment?: TAlignmentType } = {}) => {
  const lines = text.split('\n').filter(l => l.trim() !== '');
  return lines.map((line, idx) => {
    const children = [];
    if (idx === 0 && options.boldLabel) {
      children.push(new TextRun({ text: options.boldLabel, font: FONT_FAMILY, size: FONT_SIZE, bold: true }));
    }
    children.push(new TextRun({ text: line, font: FONT_FAMILY, size: FONT_SIZE, bold: options.bold }));

    return new Paragraph({
      children,
      spacing: SPACING_CONFIG,
      alignment: options.alignment ?? AlignmentType.JUSTIFIED,
      indent: idx === 0 ? undefined : options.indent,
    });
  });
};

const createRichParagraph = (
    parts: { text: string; bold?: boolean; italics?: boolean; size?: number }[], 
    options: { alignment?: TAlignmentType; indent?: { firstLine?: number } } = {}
) => {
  return new Paragraph({
    children: parts.map(part => new TextRun({
        text: part.text,
        font: FONT_FAMILY,
        size: part.size ?? FONT_SIZE,
        bold: part.bold,
        italics: part.italics,
    })),
    spacing: SPACING_CONFIG,
    alignment: options.alignment ?? AlignmentType.JUSTIFIED,
    indent: options.indent,
  });
}

const createActivitiesTable1001 = (activities: Activity1001[], t: (key: string) => string) => {
