                    new TableCell({
                        children: [
                          new Paragraph({ children: [new TextRun({ text: t('teachingMethod'), bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG }),
                          ...activity.teacherActivity.split('\n').map(l => new Paragraph({ children: [new TextRun({ text: l, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG, alignment: AlignmentType.JUSTIFIED }))
