const generateDocx1001 = (plans: LessonPlan1001[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];
    plans.forEach((plan, index) => {
        if (index > 0) children.push(new Paragraph({ pageBreakBefore: true }));

        children.push(
          new Paragraph({ text: t('lessonPlanTitle'), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, style: "Title", spacing: { ...SPACING_CONFIG, after: 120 } }),
          createRichParagraph([{text: plan.lessonTitle, bold: true, size: 28}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{text: `${t('subject')}: `, bold: true}, {text: `${plan.subject}; `}, {text: `${t('grade')}: `, bold: true}, {text: `${plan.grade}; `}, {text: `${t('periods')}: `, bold: true}, {text: String(plan.periods)}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{text: `${t('executionTime')}: `, bold: true}, {text: `${plan.executionTime} `}, {text: `(${t('docxDate')})`, italics: true}], { alignment: AlignmentType.CENTER }),

          new Paragraph({ text: t('requiredOutcomes'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
          ...createMultiParagraphs(plan.requiredOutcomes.generalCompetencies, { boldLabel: t('generalCompetencies') + " " }),
          createRichParagraph([{text: `${t('specificCompetencies')} `, bold: true}, {text: plan.requiredOutcomes.specificCompetencies}]),
          ...createMultiParagraphs(plan.requiredOutcomes.qualities, { boldLabel: t('qualities') + " " }),
          ...createMultiParagraphs(plan.requiredOutcomes.integratedContent, { boldLabel: t('integratedContent') + " " }),

          new Paragraph({ text: t('teachingAids'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
          createRichParagraph([{text: `${t('teacherAids')} `, bold: true}, {text: plan.teachingAids.teacher}]),
          createRichParagraph([{text: `${t('studentAids')} `, bold: true}, {text: plan.teachingAids.student}]),

          new Paragraph({ text: t('teachingActivities'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
          createActivitiesTable1001(plan.teachingActivities, t)
        );
    });
    return children;
};

const generateDocx5512 = (plans: LessonPlan5512[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];
    plans.forEach((plan, index) => {
        if (index > 0) children.push(new Paragraph({ pageBreakBefore: true }));

        children.push(
            new Paragraph({ text: t('lessonPlanTitle'), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, style: "Title", spacing: { ...SPACING_CONFIG, after: 120 } }),
            createRichParagraph([{text: plan.lessonTitle, bold: true, size: 28}], { alignment: AlignmentType.CENTER }),

            new Paragraph({ text: t('objectives'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
            createRichParagraph([{text: `${t('knowledge')}: `, bold: true}, {text: plan.objectives.knowledge}]),
            ...createMultiParagraphs(plan.objectives.skills, { boldLabel: `${t('skills')}: ` }),
            ...createMultiParagraphs(plan.objectives.qualities, { boldLabel: `${t('qualities')}: ` }),

            new Paragraph({ text: t('teachingProcess'), heading: HeadingLevel.HEADING_2, style: "Heading2", spacing: { ...SPACING_CONFIG, before: 120, after: 60 } }),
            ...plan.teachingProcess.flatMap(activity => [
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({ children: [new TableCell({ children: [new Paragraph({ text: activity.activityName, style: "Heading3", spacing: SPACING_CONFIG })], shading: { fill: "F2F2F2" } })] }),
                        new TableRow({ children: [new TableCell({ children: [
                            ...createMultiParagraphs(activity.objective, { boldLabel: t('objective') + " " }),
                            ...createMultiParagraphs(activity.content, { boldLabel: t('content') + " " }),
                            ...createMultiParagraphs(activity.product, { boldLabel: t('product') + " " }),
                            ...createMultiParagraphs(activity.implementation, { boldLabel: t('implementation') + " " })
                        ]})] })
                    ]
                }),
                new Paragraph({ text: "" })
            ])
        );
    });
    return children;
};

export const exportToDocx = async (plans: LessonPlan[], t: (key: string) => string, periodLabel?: string) => {
    if (!plans || plans.length === 0) return;
    const template = plans[0].template;
    const children = template === 'cv5512' ? generateDocx5512(plans as LessonPlan5512[], t) : generateDocx1001(plans as LessonPlan1001[], t);

    const doc = new Document({
      sections: [{ 
          properties: { page: { size: { width: 11906, height: 16838, orientation: PageOrientation.PORTRAIT }, margin: { top: MARGIN_TOP, bottom: MARGIN_BOTTOM, left: MARGIN_LEFT, right: MARGIN_RIGHT } } },
          children 
      }],
      styles: {
          paragraphStyles: [
