import { Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell, WidthType, BorderStyle, AlignmentType, VerticalAlign, TabStopType, TabStopPosition, PageOrientation } from 'docx';
import saveAs from 'file-saver';
import type { LessonPlan, LessonPlan1001, Activity1001, LessonPlan5512, Activity5512 } from '../types';

const FONT_FAMILY = "Times New Roman";
const FONT_SIZE = 26; // 13pt * 2
const LINE_SPACING = 240; // 1.15 approx or 1.0 depending on preference

const MARGIN_TOP = 1134;    // 2.0 cm
const MARGIN_BOTTOM = 1134; // 2.0 cm
const MARGIN_LEFT = 1701;   // 3.0 cm
const MARGIN_RIGHT = 850;   // 1.5 cm

const SPACING_CONFIG = { before: 0, after: 0, line: LINE_SPACING, lineRule: 'auto' as const };

type TAlignmentType = (typeof AlignmentType)[keyof typeof AlignmentType];

/**
 * Phân tách văn bản dựa trên dấu xuống dòng và dấu gạch đầu dòng.
 * Mỗi dòng sẽ được tạo thành một Paragraph riêng biệt.
 */
const createMultiParagraphs = (text: string, options: { boldLabel?: string; bold?: boolean; indentFirst?: number; alignment?: TAlignmentType } = {}) => {
  const lines = text.split('\n').map(l => l.trim()).filter(l => l !== '');

  return lines.map((line, idx) => {
    const children = [];

    // Nếu là dòng đầu tiên và có nhãn in đậm (ví dụ: "1. Năng lực chung: ")
    if (idx === 0 && options.boldLabel) {
      children.push(new TextRun({ text: options.boldLabel, font: FONT_FAMILY, size: FONT_SIZE, bold: true }));
    }

    children.push(new TextRun({ 
      text: line, 
      font: FONT_FAMILY, 
      size: FONT_SIZE, 
      bold: options.bold 
    }));

    return new Paragraph({
      children,
      spacing: SPACING_CONFIG,
      alignment: options.alignment ?? AlignmentType.JUSTIFIED,
      indent: (idx === 0 && options.indentFirst) ? { firstLine: options.indentFirst } : undefined,
    });
  });
};

const createRichParagraph = (
    parts: { text: string; bold?: boolean; italics?: boolean; size?: number }[], 
    options: { alignment?: TAlignmentType; indentFirst?: number } = {}
) => {
  return new Paragraph({
    children: parts.map(part => new TextRun({
        text: part.text,
        font: FONT_FAMILY,
        size: part.size ?? FONT_SIZE,
        bold: part.bold,
        italics: part.italics,
    })),
    spacing: SPACING_CONFIG,
    alignment: options.alignment ?? AlignmentType.JUSTIFIED,
    indent: options.indentFirst ? { firstLine: options.indentFirst } : undefined,
  });
}

const createActivitiesTable1001 = (activities: Activity1001[], t: (key: string) => string) => {
    const cellMargins = { left: 100, right: 100, top: 100, bottom: 100 };
    const rows = [
        new TableRow({
            children: [
                new TableCell({
                    children: [new Paragraph({ children: [new TextRun({ text: t('docxTeacherActivity'), bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG, alignment: AlignmentType.CENTER })],
                    width: { size: 50, type: WidthType.PERCENTAGE },
                    margins: cellMargins,
                    verticalAlign: VerticalAlign.CENTER,
                }),
                new TableCell({
                    children: [new Paragraph({ children: [new TextRun({ text: t('docxStudentActivity'), bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG, alignment: AlignmentType.CENTER })],
                    width: { size: 50, type: WidthType.PERCENTAGE },
                    margins: cellMargins,
                    verticalAlign: VerticalAlign.CENTER,
                }),
            ],
            tableHeader: true,
        }),
    ];

    activities.forEach(activity => {
        // Hàng Tiêu đề hoạt động + Mục tiêu
        rows.push(
            new TableRow({
                children: [
                    new TableCell({
                        children: [
                            new Paragraph({ children: [new TextRun({ text: activity.activityName, bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: SPACING_CONFIG }),
                            new Paragraph({ children: [
                                new TextRun({ text: t('objective') + " ", bold: true, italics: true, font: FONT_FAMILY, size: FONT_SIZE }),
                                new TextRun({ text: activity.objective, italics: true, font: FONT_FAMILY, size: FONT_SIZE })
                            ], spacing: SPACING_CONFIG }),
                        ],
                        columnSpan: 2,
                        margins: cellMargins,
                        shading: { fill: "F9F9F9" }
                    }),
                ],
            })
        );

        // Hàng Nội dung thực hiện
        rows.push(
            new TableRow({
                children: [
                    new TableCell({
                        children: [
                          new Paragraph({ children: [new TextRun({ text: t('teachingMethod'), bold: true, font: FONT_FAMILY, size: FONT_SIZE })], spacing: { ...SPACING_CONFIG, after: 120 } }),
                          ...createMultiParagraphs(activity.teacherActivity)
                        ],
                        verticalAlign: VerticalAlign.TOP,
                        margins: cellMargins,
                    }),
                     new TableCell({
                        children: createMultiParagraphs(activity.studentActivity),
                        verticalAlign: VerticalAlign.TOP,
                        margins: cellMargins,
                    }),
                ],
            })
        );
    });

    return new Table({ rows, width: { size: 100, type: WidthType.PERCENTAGE } });
};

const generateDocx1001 = (plans: LessonPlan1001[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];
    plans.forEach((plan, index) => {
        if (index > 0) children.push(new Paragraph({ pageBreakBefore: true }));

        children.push(
          new Paragraph({ text: t('lessonPlanTitle'), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, spacing: { ...SPACING_CONFIG, after: 120 } }),
          createRichParagraph([{text: plan.lessonTitle.toUpperCase(), bold: true, size: 28}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{text: `${t('subject')}: `, bold: true}, {text: `${plan.subject}; `}, {text: `${t('grade')}: `, bold: true}, {text: `${plan.grade}; `}, {text: `${t('periods')}: `, bold: true}, {text: String(plan.periods)}], { alignment: AlignmentType.CENTER }),
          createRichParagraph([{text: `${t('executionTime')}: `, bold: true}, {text: `${plan.executionTime} `}, {text: `(${t('docxDate')})`, italics: true}], { alignment: AlignmentType.CENTER }),

          new Paragraph({ text: t('requiredOutcomes'), heading: HeadingLevel.HEADING_2, spacing: { ...SPACING_CONFIG, before: 240, after: 120 } }),
          ...createMultiParagraphs(plan.requiredOutcomes.generalCompetencies, { boldLabel: t('generalCompetencies') + " " }),
          createRichParagraph([{text: `${t('specificCompetencies')} `, bold: true}, {text: plan.requiredOutcomes.specificCompetencies}], { spacing: { before: 120 } } as any),
          ...createMultiParagraphs(plan.requiredOutcomes.qualities, { boldLabel: t('qualities') + " " }),
          ...createMultiParagraphs(plan.requiredOutcomes.integratedContent, { boldLabel: t('integratedContent') + " " }),

          new Paragraph({ text: t('teachingAids'), heading: HeadingLevel.HEADING_2, spacing: { ...SPACING_CONFIG, before: 240, after: 120 } }),
          ...createMultiParagraphs(plan.teachingAids.teacher, { boldLabel: t('teacherAids') + " " }),
          ...createMultiParagraphs(plan.teachingAids.student, { boldLabel: t('studentAids') + " " }),

          new Paragraph({ text: t('teachingActivities'), heading: HeadingLevel.HEADING_2, spacing: { ...SPACING_CONFIG, before: 240, after: 120 } }),
          createActivitiesTable1001(plan.teachingActivities, t)
        );
    });
    return children;
};

const generateDocx5512 = (plans: LessonPlan5512[], t: (key: string) => string): (Paragraph | Table)[] => {
    const children: (Paragraph | Table)[] = [];
    plans.forEach((plan, index) => {
        if (index > 0) children.push(new Paragraph({ pageBreakBefore: true }));

        children.push(
            new Paragraph({ text: t('lessonPlanTitle'), heading: HeadingLevel.HEADING_1, alignment: AlignmentType.CENTER, spacing: { ...SPACING_CONFIG, after: 120 } }),
            createRichParagraph([{text: plan.lessonTitle.toUpperCase(), bold: true, size: 28}], { alignment: AlignmentType.CENTER }),

            new Paragraph({ text: t('objectives'), heading: HeadingLevel.HEADING_2, spacing: { ...SPACING_CONFIG, before: 240, after: 120 } }),
            ...createMultiParagraphs(plan.objectives.knowledge, { boldLabel: `${t('knowledge')}: ` }),
            ...createMultiParagraphs(plan.objectives.skills, { boldLabel: `${t('skills')}: ` }),
            ...createMultiParagraphs(plan.objectives.qualities, { boldLabel: `${t('qualities')}: ` }),

            new Paragraph({ text: t('teachingAidsAndMaterials'), heading: HeadingLevel.HEADING_2, spacing: { ...SPACING_CONFIG, before: 240, after: 120 } }),
            ...createMultiParagraphs(plan.teachingAidsAndMaterials),

            new Paragraph({ text: t('teachingProcess'), heading: HeadingLevel.HEADING_2, spacing: { ...SPACING_CONFIG, before: 240, after: 120 } }),
            ...plan.teachingProcess.flatMap(activity => [
                new Table({
                    width: { size: 100, type: WidthType.PERCENTAGE },
                    rows: [
                        new TableRow({ children: [new TableCell({ children: [new Paragraph({ text: activity.activityName, bold: true, font: FONT_FAMILY, size: FONT_SIZE })], shading: { fill: "F2F2F2" }, margins: { top: 100, bottom: 100, left: 100, right: 100 } })] }),
                        new TableRow({ children: [new TableCell({ children: [
                            ...createMultiParagraphs(activity.objective, { boldLabel: t('objective') + " " }),
                            ...createMultiParagraphs(activity.content, { boldLabel: t('content') + " " }),
                            ...createMultiParagraphs(activity.product, { boldLabel: t('product') + " " }),
                            ...createMultiParagraphs(activity.implementation, { boldLabel: t('implementation') + " " })
                        ], margins: { top: 100, bottom: 100, left: 100, right: 100 } })] })
                    ]
                }),
                new Paragraph({ text: "", spacing: { before: 120 } })
            ])
        );
    });
    return children;
};

export const exportToDocx = async (plans: LessonPlan[], t: (key: string) => string, periodLabel?: string) => {
    if (!plans || plans.length === 0) return;
    const template = plans[0].template;
    const children = template === 'cv5512' ? generateDocx5512(plans as LessonPlan5512[], t) : generateDocx1001(plans as LessonPlan1001[], t);

    const doc = new Document({
      sections: [{ 
          properties: { 
            page: { 
              size: { width: 11906, height: 16838, orientation: PageOrientation.PORTRAIT }, 
              margin: { top: MARGIN_TOP, bottom: MARGIN_BOTTOM, left: MARGIN_LEFT, right: MARGIN_RIGHT } 
            } 
          },
          children 
      }],
      styles: {
          paragraphStyles: [
              { id: "Normal", name: "Normal", run: { font: FONT_FAMILY, size: FONT_SIZE } },
              { id: "Heading1", name: "Heading 1", basedOn: "Normal", run: { font: FONT_FAMILY, size: 32, bold: true }, paragraph: { alignment: AlignmentType.CENTER } },
              { id: "Heading2", name: "Heading 2", basedOn: "Normal", run: { font: FONT_FAMILY, size: 28, bold: true } },
          ]
      }
    });

    const blob = await Packer.toBlob(doc);
    saveAs(blob, `GiaoAn_${plans[0].subject}_${plans[0].lessonTitle.replace(/\s+/g, '_')}.docx`);
};

